import{_ as a,o as e,c as s,ao as i}from"./chunks/framework.CSWjgcox.js";const g=JSON.parse('{"title":"Exact-Gaussian Diagnostics","description":"","frontmatter":{},"headers":[],"relativePath":"diagnostics-and-validation/exact-gaussian-diagnostics.md","filePath":"diagnostics-and-validation/exact-gaussian-diagnostics.md","lastUpdated":null}'),n={name:"diagnostics-and-validation/exact-gaussian-diagnostics.md"};function o(r,t,d,l,c,p){return e(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="Exact-Gaussian-Diagnostics" tabindex="-1">Exact-Gaussian Diagnostics <a class="header-anchor" href="#Exact-Gaussian-Diagnostics" aria-label="Permalink to &quot;Exact-Gaussian Diagnostics {#Exact-Gaussian-Diagnostics}&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Status - developer evidence</p><p>This page tracks exact-Gaussian diagnostic lanes that are useful for source-code review and future parity work. It is not a public optimizer promotion, not an R bridge promotion, and not interval-coverage evidence.</p></div><h2 id="Current-Row-Contract-Donor" tabindex="-1">Current Row-Contract Donor <a class="header-anchor" href="#Current-Row-Contract-Donor" aria-label="Permalink to &quot;Current Row-Contract Donor {#Current-Row-Contract-Donor}&quot;">​</a></h2><p>The location-only phylogenetic mean lane lives in <code>src/location_only.jl</code>. Its current row contract is guarded by <code>test/test_location_only_reml_mme.jl</code> and the validation artifacts under <code>docs/dev-log/validation-status/</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Route</th><th style="text-align:right;">Estimator status</th><th style="text-align:right;">Diagnostic rows</th><th style="text-align:right;">Boundary</th></tr></thead><tbody><tr><td style="text-align:right;"><code>gaussian_loconly_phylo_reml</code></td><td style="text-align:right;">Exact-Gaussian location-only REML diagnostics</td><td style="text-align:right;">comparator plan, external package/version probe, derivative finite-difference status, guarded line-search status, boundary grid, profile-axis sanity, variance-component point status</td><td style="text-align:right;">Internal developer evidence only: no q4 claim, no non-Gaussian claim, no R bridge promotion, no interval coverage claim, and <code>ai_reml_ready = false</code>.</td></tr></tbody></table><h2 id="Second-Sparse-Candidate" tabindex="-1">Second Sparse Candidate <a class="header-anchor" href="#Second-Sparse-Candidate" aria-label="Permalink to &quot;Second Sparse Candidate {#Second-Sparse-Candidate}&quot;">​</a></h2><p>The two-structured Gaussian sparse route lives in <code>src/gaussian_structured.jl</code> and is guarded by <code>test/test_two_structured_gaussian_sparse.jl</code>. It fits Gaussian mean models with two structured random-effect terms by integrating the augmented latent vector with sparse linear algebra.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>y = X beta + Z1 a1 + Z2 a2 + epsilon</span></span>
<span class="line"><span>a1 ~ N(0, sigma1^2 C1)</span></span>
<span class="line"><span>a2 ~ N(0, sigma2^2 C2)</span></span>
<span class="line"><span>epsilon ~ N(0, sigma^2 I)</span></span></code></pre></div><p>The sparse path uses one sparse Cholesky of</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>H = blockdiag(sigma1^-2 C1^-1, sigma2^-2 C2^-1) + Z&#39;Z / sigma^2</span></span></code></pre></div><p>and reads variance-component gradient terms from Takahashi selected-inverse entries. This makes it a plausible candidate for later row-shaped diagnostics. At this stage it remains a source-map candidate for the Gaussian ML route, not a REML or AI-REML claim.</p><h2 id="Evidence-Gates" tabindex="-1">Evidence Gates <a class="header-anchor" href="#Evidence-Gates" aria-label="Permalink to &quot;Evidence Gates {#Evidence-Gates}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Artifact</th><th style="text-align:right;">What It Supports</th><th style="text-align:right;">What It Does Not Support</th></tr></thead><tbody><tr><td style="text-align:right;"><code>docs/dev-log/scout/2026-06-22-exact-gaussian-structured-source-map.md</code></td><td style="text-align:right;">Source map from the current REML diagnostic donor to the two-structured Gaussian sparse candidate.</td><td style="text-align:right;">Any new estimator, bridge, coverage, q4, or non-Gaussian claim.</td></tr><tr><td style="text-align:right;"><code>test/test_two_structured_gaussian_sparse.jl</code></td><td style="text-align:right;">Dense/sparse agreement, gradient sanity, recovery smoke, and public <code>algorithm = :sparse</code> routing for the two-structured Gaussian ML route.</td><td style="text-align:right;">REML/AI-REML status or interval calibration.</td></tr><tr><td style="text-align:right;"><code>test/test_location_only_reml_mme.jl</code></td><td style="text-align:right;">Exact-Gaussian location-only REML diagnostic row contracts.</td><td style="text-align:right;">q4 Patterson-Thompson REML, non-Gaussian Laplace routes, or R bridge parity.</td></tr></tbody></table><h2 id="Claim-Boundaries" tabindex="-1">Claim Boundaries <a class="header-anchor" href="#Claim-Boundaries" aria-label="Permalink to &quot;Claim Boundaries {#Claim-Boundaries}&quot;">​</a></h2><ul><li><p>REML and AI-REML wording here is exact-Gaussian only.</p></li><li><p>q4 Patterson-Thompson REML is not HSquared AI-REML.</p></li><li><p>Non-Gaussian Laplace routes keep their own method names.</p></li><li><p>R bridge support needs row-specific native R, direct DRM.jl, and R-via-Julia evidence before promotion.</p></li><li><p>Profile-axis diagnostics are not interval coverage.</p></li><li><p>No Ayumi-facing reply or draft is changed by these diagnostics.</p></li></ul>`,15)])])}const h=a(n,[["render",o]]);export{g as __pageData,h as default};
